metrics.workdir_dsl:
workspace "Parcel Tracker" "C4 model of the parcel delivery tracking platform" {
    model {
        customer = person "Customer" "Looks up the status of their parcels"

        parcelTracker = softwareSystem "Parcel Tracker" "Owned and operated by our company" {
            webPortal = container "Web Portal" "Where customers look up shipments"
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers"
            database = container "Database" "Stores shipments and dispatch records"
        }

        pricingRulesLibrary = softwareSystem "Pricing Rules Library" "Computes delivery prices from weight and zone"
        emailProvider = softwareSystem "Email Delivery Provider" "Operated by a different organization"

        customer -> webPortal "Looks up the status of their parcels"
        webPortal embeds pricingRulesLibrary
        dispatchService embeds pricingRulesLibrary
        dispatchService -> emailProvider "Sends customer notification emails"
        webPortal -> database "Stores and retrieves shipments"
        dispatchService -> database "Stores dispatch records"
    }

    views {
        systemContext parcelTracker "SystemContext" "System context diagram for Parcel Tracker" {
            include *
            autoLayout
        }

        container parcelTracker "Containers" "Container diagram for Parcel Tracker" {
            include *
            autoLayout
        }
    }
}
